.markdown-body ul ul ul:not([data-type="taskList"]) > li:not(.task-list-item) { list-style-type: square; }
.markdown-body ol { counter-reset: markie-ol; }
.markdown-body ol > li { counter-increment: markie-ol; }
.markdown-body ol > li::marker { content: counters(markie-ol, ".") ". "; }
.markdown-body li::marker { color: var(--foreground); }
.markdown-body thead th, .markdown-body tbody th, .markdown-body tbody td { border: 1px solid var(--doc-rule); }
.markdown-body thead th, .markdown-body tbody th { text-transform: none; letter-spacing: 0; font-size: 1em; font-weight: 600; color: var(--foreground); background: var(--accent); }
.markdown-body thead th, .markdown-body tbody th { padding: 0.3em 0.65em; }
.markdown-body tbody td { padding: 0.28em 0.65em; }
.markdown-body table { display: table; width: 100%; }
.markdown-body blockquote { border-left-color: var(--blue); }
.markdown-body blockquote { border: 1px solid var(--doc-rule); border-radius: 8px; padding: 0.7em 1.1em; }
.markdown-body pre { border: none; border-left: 3px solid var(--muted); border-radius: 0; }
.markdown-body a:not([data-doc-link="none"]) { border-bottom: 1px solid color-mix(in srgb, var(--blue) 55%, transparent); }

styles.appCss:
